mapper.select:
SELECT COUNT(1)
FROM TB_EVRC_BRDCT
WHERE 1=1

        AND USE_YN = #{useYn}


        AND BRD_CTID_NM = #{brdCtidNm}


        AND BRD_FRRG_TS >= CAST(#{brdFrrgTs} AS DATE)

SELECT TB.*
FROM (
    SELECT ROW_NUMBER() OVER (ORDER BY TA.BRD_CTID) AS RNUM, TA.*
    FROM (

        FROM TB_EVRC_BRDCT
        WHERE 1=1

        AND USE_YN = #{useYn}


        AND BRD_CTID_NM = #{brdCtidNm}


        AND BRD_FRRG_TS >= CAST(#{brdFrrgTs} AS DATE)

    ORDER BY BRD_CTID
    ) TA
) TB
WHERE TB.RNUM BETWEEN #{start} AND #{end}
ORDER BY TB.RNUM

FROM TB_EVRC_BRDCT WHERE 1=1
AND USE_YN = #{useYn}
AND BRD_CTID_NM = #{brdCtidNm}
AND BRD_FRRG_TS >= CAST(#{brdFrrgTs} AS DATE)
ORDER BY BRD_CTID LIMIT #{listCount} OFFSET (#{start} - 1)

update.foreach:
UPDATE TB_EVRC_BRDCT
SET USE_YN = #{map.useYn}
WHERE BRD_CTID = #{map.brdCtid}
